/**
 *  A sync tool whose folder holds a folder remote: supported, since each
 *  machine writes only its own subfolder (SPEC 9.6).
 */
export type SyncTool = "resilio" | "syncthing" | "one_drive" | "dropbox" | "google_drive";

export type TagEntry = {
	name: string,
	kind: TagKindDto,
	commit: string,
	message: string | null,
	/**  RFC 3339, UTC. */
	time: string | null,
};

export type TagKindDto = "user" | "auto";

/**
 *  A watched target file or folder changed outside Loadout's views: the
 *  pending plan, the pills and the effective views are stale.
 */
export type TargetsChanged = null;

export type TierKind = "a" | "b" | "c" | "d";

export type ToolFile = {
	path: string,
	exists: boolean,
};

/**  One client on the Tools page. */
export type ToolInfo = {
	id: string,
	name: string,
	tier: TierKind,
	detected: boolean,
	/**  Has an MCP config on this operating system. */
	supported: boolean,
	/**  Loadout only reads this client (`vscode-legacy`). */
	readOnly: boolean,
	/**  User-scope MCP files (the first existing one is used). */
	userFiles: ToolFile[],
	/**
	 *  Project files, relative to the project folder (`<P>/...`) or absolute
	 *  for a user file keyed by project.
	 */
	projectFiles: string[],
	transports: Transports,
	/**  The client expands environment references (`${env:NAME}`) itself. */
	envRefs: boolean,
	/**  The client reads its file only at launch. */
	restartRequired: boolean,
	warnings: IpcError[],
	/**
	 *  Where to get the client, from [`HOMEPAGES`]; opened by
	 *  `open_tool_homepage` with the client id.
	 */
	homepage: string | null,
};

/**  One client's skill folder in the page's scope. */
export type ToolSkillDir = {
	client: string,
	name: string,
	dir: string,
	exists: boolean,
	entries: ToolSkillEntry[],
};

export type ToolSkillEntry = {
	name: string,
	path: string,
	class: SkillEntryClass,
	linkTarget: string | null,
	/**  The store skill of a managed entry. */
	skillId: string | null,
	description: string | null,
};

export type TransportKind = "stdio" | "http" | "sse";

export type Transports = {
	stdio: boolean,
	http: boolean,
	sse: boolean,
};

/**  The trust review of a project: what trusting it would accept. */
export type TrustReview = {
	id: string,
	name: string,
	path: string,
	trust: ProjectTrust,
	/**
	 *  The manifests' content hash; `trust_project` trusts only this
	 *  content.
	 */
	hash: string,
	files: ReviewedFile[],
	/**  Manifest validation warnings. */
	warnings: IpcError[],
};

export type UndoResult = {
	applyId: string,
	/**  Store files restored from before the run. */
	restored: string[],
	/**  The `auto/pre-rollback/<ts>` tag. */
	tag: string,
	commit: string | null,
	apply: ApplyRun,
};

/**  A newer release the check found. */
export type UpdateOffer = {
	version: string,
	currentVersion: string,
	/**  Release notes from the update feed, if any. */
	notes: string | null,
};

/**  What Settings > Updates shows. */
export type UpdaterStatus = {
	/**
	 *  This build carries the updater (else the section says updates come
	 *  from the package manager or the releases page).
	 */
	available: boolean,
	/**  The Settings switch; on unless turned off. */
	enabled: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
